import os, pwd, grp, subprocess

# 1. Current identity
print("user:", pwd.getpwuid(os.getuid()).pw_name, "(uid=%d, gid=%d)" % (os.getuid(), os.getgid()))
print("groups:", [grp.getgrgid(g).gr_name for g in os.getgroups()])

# 2. sudo -n probe (non-interactive)
try:
    r = subprocess.run(["sudo","-n","true"], capture_output=True, text=True, timeout=10)
    print("sudo -n true rc:", r.returncode, "stderr:", r.stderr.strip())
except Exception as e:
    print("sudo probe error:", e)

# 3. sudo -n -l (list allowed commands)
try:
    r = subprocess.run(["sudo","-n","-l"], capture_output=True, text=True, timeout=10)
    print("sudo -n -l rc:", r.returncode)
    print(r.stdout.strip() or r.stderr.strip())
except Exception as e:
    print("sudo -l error:", e)

# 4. setuid binaries
print("\nsetuid binaries:")
found = []
for root, dirs, files in os.walk("/"):
    # skip noisy/virtual trees
    dirs[:] = [d for d in dirs if d not in ("proc","sys","dev","run","snap")]
    for f in files:
        p = os.path.join(root, f)
        try:
            st = os.lstat(p)
        except OSError:
            continue
        if st.st_mode & 0o4000:
            found.append((p, oct(st.st_mode & 0o7777), st.st_uid))
for p, mode, uid in found:
    print(f"  {p}  mode={mode} owner_uid={uid}")
if not found:
    print("  (none found)")

